{
  "findings": [
    {
      "ref": "[D543]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with your child if Experience chat is set to Everyone.",
      "stance": "risk",
      "quote": "Choose from Everyone or No one."
    },
    {
      "ref": "[D543]",
      "area": "contact",
      "claim": "A parent reports that direct messages are blocked automatically when Experience chat is set to No one.",
      "stance": "mitigation",
      "quote": "Note that if you chose ‘No one’ for Experience chat, Direct chat will automatically be No one as well."
    },
    {
      "ref": "[D543]",
      "area": "contact",
      "claim": "A parent reports that Party communication can be limited to Friends or No one for children under 13.",
      "stance": "mitigation",
      "quote": "For children under 13, this is limited to Friends or No one."
    },
    {
      "ref": "[D543]",
      "area": "money",
      "claim": "A parent reports that Roblox encourages in‑game spending using Robux, which is purchased with real money.",
      "stance": "risk",
      "quote": "Some experiences on Roblox encourage in-game spending. Outside of experiences, there are also various items users can buy for their avatar using Robux. Robux costs real currency."
    },
    {
      "ref": "[D543]",
      "area": "money",
      "claim": "A parent reports that spending can be limited by setting a monthly spending limit in the Parental Controls menu.",
      "stance": "mitigation",
      "quote": "Step 1 – Navigate to the Parental Controls menu. Scroll down and tap Spending restrictions. Tap Monthly spending limit. Step 2 – Enter the amount you’re happy with your child spending on a monthly basis. Tap Update."
    },
    {
      "ref": "[D543]",
      "area": "money",
      "claim": "A parent reports that spending notifications can be turned on to alert you about every transaction.",
      "stance": "mitigation",
      "quote": "We recommend tracking all transactions, particularly if you don’t have spending limits in place."
    },
    {
      "ref": "[D543]",
      "area": "data",
      "claim": "A parent reports that the platform may collect data for ads or share it with third parties, and that data can be deleted.",
      "stance": "neutral",
      "quote": "Read our privacy policy for more information on how we use your data."
    },
    {
      "ref": "[D543]",
      "area": "age_gating",
      "claim": "A parent reports that age‑gating is enforced by requiring users to verify their age to access certain features such as Trusted Connections.",
      "stance": "mitigation",
      "quote": "Step 1 – On your teen’s account, go to More > Settings > Account Info. Tap Verify My Age and follow the verification instructions."
    },
    {
      "ref": "[D543]",
      "area": "content",
      "claim": "A parent reports that reviewers have observed users being able to see each other’s inventories, which can lead to manipulation attempts.",
      "stance": "risk",
      "quote": "If a stranger can see your child’s inventory and notices there’s an item they want, they might try to manipulate your child to give it to them."
    },
    {
      "ref": "[D543]",
      "area": "developer_record",
      "claim": "A parent reports that Roblox has faced regulatory scrutiny under the UK Online Safety Act for illegal content reporting.",
      "stance": "risk",
      "quote": "You can also report illegal content under the UK Online Safety Act (UK only)."
    }
  ]
}
